  static TransactionResultResult txtooLate() { TransactionResultResult r; r.t_ = TransactionResultCode::txTOO_LATE; r.v_.template emplace<2>(); return r; }
  static TransactionResultResult txmissingOperation() { TransactionResultResult r; r.t_ = TransactionResultCode::txMISSING_OPERATION; r.v_.template emplace<2>(); return r; }
  static TransactionResultResult txbadSeq() { TransactionResultResult r; r.t_ = TransactionResultCode::txBAD_SEQ; r.v_.template emplace<2>(); return r; }
